import * as THREE from 'three/webgpu';
import { texture, uv, vec2, vec3, float, uniform, mix, positionLocal, normalLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'home-quote-panel';
  group.position.set(-2.5, -1.1, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const imageUrl = '/prism-mock/home/nodes/parallax-stack.png';
  const depthUrl = '/prism-mock/home/nodes/parallax-stack.depth.png';

  const colorMap = ctx.textureLoader.load(imageUrl);
  const depthMap = ctx.textureLoader.load(depthUrl);
  colorMap.colorSpace = THREE.SRGBColorSpace;

  const colorTex = texture(colorMap);
  const depthTex = texture(depthMap);

  const displacementStrength = uniform(0.08);
  const rimStrength = uniform(0.6);
  const accentColor = vec3(1.0, 0.1647, 0.2196);

  const dispAmount = depthTex.r.mul(displacementStrength);
  const displacedPosition = positionLocal.add(normalLocal.mul(dispAmount));

  const rim = float(1.0).sub(uv().y.oneMinus().abs()).pow(3.0).mul(rimStrength);
  const baseColor = colorTex.rgb;
  const finalColor = mix(baseColor, accentColor, rim.mul(0.25));

  const material = new THREE.MeshPhysicalNodeMaterial();
  material.colorNode = finalColor;
  material.positionNode = displacedPosition;
  material.roughness = 0.55;
  material.metalness = 0.5;
  material.clearcoat = 0.2;
  material.clearcoatRoughness = 0.4;

  const geometry = new THREE.PlaneGeometry(2.4, 1.5, 64, 64);
  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'home-quote-panel-mesh';

  // atlas region crop applied via UV transform (source rect 0,0,512,320 within atlas 0)
  const atlasW = 512, atlasH = 320;
  const uAttr = geometry.attributes.uv;
  for (let i = 0; i < uAttr.count; i++) {
    const u = uAttr.getX(i);
    const v = uAttr.getY(i);
    uAttr.setXY(i, u * (512 / atlasW), v * (320 / atlasH));
  }
  uAttr.needsUpdate = true;

  group.add(mesh);

  // frame / rim edge as machined-metal accent border
  const frameGeo = new THREE.PlaneGeometry(2.5, 1.6);
  const frameMat = new THREE.MeshPhysicalNodeMaterial({
    color: new THREE.Color('#16161d'),
    roughness: 0.6,
    metalness: 0.45,
    clearcoat: 0.15,
  });
  const frame = new THREE.Mesh(frameGeo, frameMat);
  frame.position.z = -0.01;
  group.add(frame);

  // Apply cinematic primitives
  ctx.primitives['parallax-scroll'](mesh, { intensity: 0.4 });
  ctx.primitives['depth-rotate'](group, { maxDeg: 8 });

  // Interaction state
  let hovering = false;
  const baseY = group.position.y;
  let riseTween = null;

  function onHoverStart() {
    if (hovering) return;
    hovering = true;
    if (riseTween) riseTween.kill();
    riseTween = gsap.timeline()
      .to(group.position, { y: baseY + 0.15, duration: 0.35, ease: 'power2.out' })
      .to(mesh.scale, { x: 1.02, y: 1.02, z: 1.02, duration: 0.35, ease: 'power2.out' }, 0);
  }

  function onHoverEnd() {
    if (!hovering) return;
    hovering = false;
    if (riseTween) riseTween.kill();
    riseTween = gsap.timeline()
      .to(group.position, { y: baseY, duration: 0.35, ease: 'power2.out' })
      .to(mesh.scale, { x: 1, y: 1, z: 1, duration: 0.35, ease: 'power2.out' }, 0);
  }

  function onClick() {
    gsap.timeline()
      .to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' })
      .to(group.scale, { x: 1, y: 1, z: 1, duration: 0.2, ease: 'back.out' });
    if (ctx.emit) {
      ctx.emit('hub-home.select', { source: 'home-quote-panel' });
    }
  }

  // Weighted-settle entrance animation
  group.scale.set(0.96, 0.96, 0.96);
  const entranceTween = gsap.timeline()
    .to(group.scale, {
      x: 1.04, y: 1.04, z: 1.04, duration: 0.5, ease: 'power4.out',
    })
    .to(group.scale, {
      x: 1, y: 1, z: 1, duration: 0.4, ease: 'power4.out',
    });

  group.userData.handlers = {
    onPointerOver: onHoverStart,
    onPointerOut: onHoverEnd,
    onClick: onClick,
  };

  group.userData.cleanup = () => {
    if (riseTween) riseTween.kill();
    if (entranceTween) entranceTween.kill();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(mesh.scale);

    geometry.dispose();
    frameGeo.dispose();
    material.dispose();
    frameMat.dispose();
    colorMap.dispose();
    depthMap.dispose();
  };

  return group;
}
